(function() {
    'use strict';

    class MacroEconAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Entorno Económico Global';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    scenarioKey: 'round1',
                    brazilReturn: -0.12,
                    mexicoReturn: -0.06,
                    andeanReturn: -0.04,
                    hedgeBenefit: 0.08
                },
                {
                    scenarioKey: 'round2',
                    brazilReturn: -0.08,
                    mexicoReturn: -0.03,
                    andeanReturn: -0.02,
                    hedgeBenefit: 0.05
                },
                {
                    scenarioKey: 'round3',
                    brazilReturn: -0.18,
                    mexicoReturn: 0.02,
                    andeanReturn: 0.01,
                    hedgeBenefit: 0.06
                },
                {
                    scenarioKey: 'round4',
                    brazilReturn: 0.04,
                    mexicoReturn: 0.05,
                    andeanReturn: 0.08,
                    hedgeBenefit: -0.03
                },
                {
                    scenarioKey: 'round5',
                    brazilReturn: -0.10,
                    mexicoReturn: -0.04,
                    andeanReturn: -0.07,
                    hedgeBenefit: 0.10
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    portfolio: 100000000,
                    initialPortfolio: 100000000,
                    cumulativeReturn: 0,
                    portfolioHistory: [],
                    returnHistory: [],
                    riskHistory: [],
                    brazilAllocHistory: [],
                    mexicoAllocHistory: [],
                    andeanAllocHistory: [],
                    cashAllocHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    brazilAlloc: 15,
                    mexicoAlloc: 10,
                    andeanAlloc: 15,
                    hedgeRatio: 20
                };
            }
            this._updateBriefing(state);
            this._setupCashCalculator();
        }

        validateDecisions(decisions) {
            var brazilEl = document.getElementById('brazilInput');
            var mexicoEl = document.getElementById('mexicoInput');
            var andeanEl = document.getElementById('andeanInput');
            var hedgeEl = document.getElementById('hedgeInput');

            if (brazilEl) decisions.brazilAlloc = parseFloat(brazilEl.value);
            if (mexicoEl) decisions.mexicoAlloc = parseFloat(mexicoEl.value);
            if (andeanEl) decisions.andeanAlloc = parseFloat(andeanEl.value);
            if (hedgeEl) decisions.hedgeRatio = parseFloat(hedgeEl.value);

            if (isNaN(decisions.brazilAlloc) || decisions.brazilAlloc < 0 || decisions.brazilAlloc > 40) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('brazil_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.mexicoAlloc) || decisions.mexicoAlloc < 0 || decisions.mexicoAlloc > 30) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('mexico_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.andeanAlloc) || decisions.andeanAlloc < 0 || decisions.andeanAlloc > 30) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('andean_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.hedgeRatio) || decisions.hedgeRatio < 0 || decisions.hedgeRatio > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('hedge_warning'), 'warning'
                );
                return false;
            }

            var totalEM = decisions.brazilAlloc + decisions.mexicoAlloc + decisions.andeanAlloc;
            if (totalEM > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('overalloc_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var brazilW = d.brazilAlloc / 100;
            var mexicoW = d.mexicoAlloc / 100;
            var andeanW = d.andeanAlloc / 100;
            var emTotal = brazilW + mexicoW + andeanW;
            var cashW = 1 - emTotal;
            var hedgeW = d.hedgeRatio / 100;

            var brazilPnL = brazilW * round.brazilReturn;
            var mexicoPnL = mexicoW * round.mexicoReturn;
            var andeanPnL = andeanW * round.andeanReturn;
            var hedgePnL = hedgeW * emTotal * round.hedgeBenefit;
            var hedgeCost = hedgeW * emTotal * 0.005;
            var cashReturn = cashW * 0.01;

            var periodReturn = brazilPnL + mexicoPnL + andeanPnL + hedgePnL - hedgeCost + cashReturn;
            var periodReturnPct = periodReturn * 100;

            var pnlUSD = ds.portfolio * periodReturn;
            ds.portfolio = ds.portfolio + pnlUSD;

            var cumReturn = ((ds.portfolio / ds.initialPortfolio) - 1) * 100;
            ds.cumulativeReturn = cumReturn;

            var brazilRisk = Math.max(0, d.brazilAlloc - 20) * 2.5;
            var emRisk = Math.max(0, emTotal * 100 - 60) * 1.2;
            var hedgeDeficit = Math.max(0, (emTotal * 100) - d.hedgeRatio) * 0.4;
            var riskScore = Math.min(100, Math.round(brazilRisk + emRisk + hedgeDeficit));

            ds.portfolioHistory.push(ds.portfolio);
            ds.returnHistory.push(periodReturnPct);
            ds.riskHistory.push(riskScore);
            ds.brazilAllocHistory.push(d.brazilAlloc);
            ds.mexicoAllocHistory.push(d.mexicoAlloc);
            ds.andeanAllocHistory.push(d.andeanAlloc);
            ds.cashAllocHistory.push(Math.round(cashW * 100));

            // --- Persist a 0-100 overall score for the grading/reporting layer ---
            // Contract: the DB grade + reports resolve domainState.performance.overallScore, then domainState.score.
            // No 0-100 score existed. Derived transparently from the two metrics the sim grades on:
            //   cumulative return (0-70 pts: -20% -> 0, +10% -> 70) + low average risk (0-30 pts: risk 0 -> 30, 60+ -> 0).
            // NOTE: newly-introduced normalisation (see review; tune bands/weights to taste).
            var _avgRisk = ds.riskHistory.reduce(function(s, r) { return s + r; }, 0) / ds.riskHistory.length;
            var _retPart = Math.max(0, Math.min(70, ((ds.cumulativeReturn + 20) / 30) * 70));
            var _riskPart = Math.max(0, Math.min(30, ((60 - _avgRisk) / 60) * 30));
            var overallScore = Math.round(Math.max(0, Math.min(100, _retPart + _riskPart)));
            var perfGrade = 'Beginner';
            if (overallScore >= 80) perfGrade = 'Excellent';
            else if (overallScore >= 65) perfGrade = 'Very Good';
            else if (overallScore >= 50) perfGrade = 'Good';
            ds.score = overallScore;
            ds.performance = { overallScore: overallScore, grade: perfGrade };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: overallScore,
                score: overallScore,
                brazilAlloc: d.brazilAlloc,
                mexicoAlloc: d.mexicoAlloc,
                andeanAlloc: d.andeanAlloc,
                cashAlloc: Math.round(cashW * 100),
                hedgeRatio: d.hedgeRatio,
                periodReturn: periodReturnPct,
                pnlUSD: pnlUSD,
                portfolio: ds.portfolio,
                riskScore: riskScore,
                scenario: round.scenarioKey
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('portfolioDisplay', 'domainState.portfolio',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('returnDisplay', 'results.periodReturn',
                (v) => {
                    if (v === undefined || v === null) return '—';
                    var sign = v >= 0 ? '+' : '';
                    return sign + v.toFixed(2) + '%';
                });
            uiManager.bind('cumReturnDisplay', 'domainState.cumulativeReturn',
                (v) => {
                    var sign = v >= 0 ? '+' : '';
                    return sign + v.toFixed(2) + '%';
                });
            uiManager.bind('riskDisplay', 'results.riskScore',
                (v) => (v === undefined || v === null) ? '—' : v + '/100');
        }

        getChartConfig() {
            return {
                portfolioChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Portfolio Value (M USD)',
                            data: [],
                            borderColor: '#00ff88',
                            backgroundColor: 'rgba(0,255,136,0.08)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2,
                            pointBackgroundColor: '#00ff88',
                            pointBorderColor: '#0a0f1e',
                            pointBorderWidth: 2,
                            pointRadius: 5
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Portfolio Value', color: '#6b7e99', font: { family: 'Courier New', size: 12 } },
                            legend: { labels: { color: '#6b7e99', font: { family: 'Courier New', size: 10 } } }
                        },
                        scales: {
                            x: { ticks: { color: '#4a5568', font: { family: 'Courier New' } }, grid: { color: 'rgba(31,45,61,0.4)' } },
                            y: { ticks: { color: '#4a5568', font: { family: 'Courier New' }, callback: function(v) { return '$' + (v/1000000).toFixed(0) + 'M'; } }, grid: { color: 'rgba(31,45,61,0.4)' } }
                        }
                    }
                },
                allocationChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Brazil', data: [], backgroundColor: '#ff4757', borderWidth: 0 },
                            { label: 'Mexico', data: [], backgroundColor: '#00bfff', borderWidth: 0 },
                            { label: 'Andean', data: [], backgroundColor: '#ffa94d', borderWidth: 0 },
                            { label: 'Cash', data: [], backgroundColor: '#2a4060', borderWidth: 0 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Allocation by Round', color: '#6b7e99', font: { family: 'Courier New', size: 12 } },
                            legend: { labels: { color: '#6b7e99', font: { family: 'Courier New', size: 10 } } }
                        },
                        scales: {
                            x: { stacked: true, ticks: { color: '#4a5568', font: { family: 'Courier New' } }, grid: { color: 'rgba(31,45,61,0.4)' } },
                            y: { stacked: true, max: 100, ticks: { color: '#4a5568', font: { family: 'Courier New' }, callback: function(v) { return v + '%'; } }, grid: { color: 'rgba(31,45,61,0.4)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.portfolioHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                portfolioChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.portfolioHistory }]
                },
                allocationChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.brazilAllocHistory },
                        { data: state.domainState.mexicoAllocHistory },
                        { data: state.domainState.andeanAllocHistory },
                        { data: state.domainState.cashAllocHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var returns = history.map(function(r) { return r.results ? r.results.periodReturn : 0; });
            var risks = history.map(function(r) { return r.results ? r.results.riskScore : 0; });
            var finalPortfolio = history[history.length - 1].results ? history[history.length - 1].results.portfolio : 100000000;
            var totalReturn = ((finalPortfolio / 100000000) - 1) * 100;
            var avgReturn = returns.reduce(function(s, r) { return s + r; }, 0) / returns.length;
            var avgRisk = risks.reduce(function(s, r) { return s + r; }, 0) / risks.length;
            var sharpe = avgRisk > 0 ? (avgReturn / (avgRisk / 20)).toFixed(2) : 'N/A';

            var _retPart = Math.max(0, Math.min(70, ((totalReturn + 20) / 30) * 70));
            var _riskPart = Math.max(0, Math.min(30, ((60 - avgRisk) / 60) * 30));
            var overallScore = Math.round(Math.max(0, Math.min(100, _retPart + _riskPart)));

            var performance = 'Beginner';
            if (totalReturn > -5 && avgRisk < 50) performance = 'Good';
            if (totalReturn > 0 && avgRisk < 35) performance = 'Very Good';
            if (totalReturn > 5 && avgRisk < 25) performance = 'Excellent';

            var insights = [];
            if (totalReturn > 5) {
                insights.push('Outstanding portfolio management — positive returns despite volatile scenarios.');
            } else if (totalReturn > 0) {
                insights.push('Solid risk management — the portfolio preserved capital through turbulence.');
            } else if (totalReturn > -10) {
                insights.push('Reasonable performance — consider higher hedging and lower Brazil exposure in crises.');
            } else {
                insights.push('Heavy losses suggest over-concentration in high-risk markets. Diversification and hedging are key.');
            }

            if (avgRisk > 50) {
                insights.push('Average risk score was elevated. Consider limiting Brazil below 20% during stress events.');
            }

            return {
                overallScore: overallScore,
                score: overallScore,
                finalPortfolio: '$' + Math.round(finalPortfolio).toLocaleString(),
                totalReturn: totalReturn.toFixed(2) + '%',
                avgRisk: Math.round(avgRisk) + '/100',
                riskAdjustedScore: sharpe,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.periodReturn < -5) return window.mySimulation.t('hint_heavy_loss');
            if (results.riskScore > 60) return window.mySimulation.t('hint_high_risk');
