        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = window.mySimulation.t(round.scenarioKey + '_title');

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = window.mySimulation.t(round.scenarioKey + '_brief');
        }

        _setupCashCalculator() {
            var ids = ['brazilInput', 'mexicoInput', 'andeanInput'];
            var self = this;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() { self._updateCashDisplay(); });
                }
            });
            this._updateCashDisplay();
        }

        _updateCashDisplay() {
            var brazilEl = document.getElementById('brazilInput');
            var mexicoEl = document.getElementById('mexicoInput');
            var andeanEl = document.getElementById('andeanInput');
            var brazil = brazilEl ? (parseFloat(brazilEl.value) || 0) : 0;
            var mexico = mexicoEl ? (parseFloat(mexicoEl.value) || 0) : 0;
            var andean = andeanEl ? (parseFloat(andeanEl.value) || 0) : 0;
            var cash = 100 - brazil - mexico - andean;
            var el = document.getElementById('cashPctDisplay');
            if (el) {
                el.textContent = cash + '%';
                el.style.color = cash < 0 ? '#ff4757' : '#00bfff';
            }
        }
